counts={'a':None};total=0;word='before'
try:
 for word in ('a','b'): counts[word]=counts.get(word,0)+1;total+=1
except TypeError: print(counts,total,word)

events=[]
class Mapping:
 def __init__(self): self.data={}
 def get(self,key,default): events.append('get');return self.data.get(key,default)
 def __setitem__(self,key,value): events.append('set');self.data[key]=value
counts=Mapping();total=0
for word in ('a','a'): counts[word]=counts.get(word,0)+1;total+=1
print(counts.data,total,events)
